contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount, uint256 extraMint) public payable {
        // setup: obtain stakeable tokens by minting to this test contract
        IERC20 st = c.stakingToken();
        require(extraMint > 0 && stakeAmount > 0 && withdrawAmount > 0, "params");
        // fund this contract with staking tokens; assume token has a public mint and we are allowed
        // Use try/catch to avoid reverting if mint is unavailable — but we need it.
        // Instead, rely on the fact that this is a mock token with mint(address,uint256).
        (bool okMint, ) = address(st).call(abi.encodeWithSignature("mint(address,uint256)", address(this), stakeAmount + extraMint));
        require(okMint, "mint failed");

        // approve and stake so c has stakers
        st.approve(address(c), stakeAmount);
        c.stake(stakeAmount);

        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        require(balBefore >= withdrawAmount, "withdrawAmount too big");

        c.withdraw(withdrawAmount, false);

        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        // The general rule: user balance decreases exactly by withdrawAmount,
        // totalSupply decreases exactly by withdrawAmount, and the staking token balance held
        // by c is at least equal to the remaining totalSupply (no under-collateralization).
        uint256 stakerTokenBalance = st.balanceOf(address(c));
        assert(balAfter == balBefore - withdrawAmount && supplyAfter == supplyBefore - withdrawAmount && stakerTokenBalance >= supplyAfter);
    }

    receive() external payable {}
}

