contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        c.getRewards(address(this));

        assert(
            _allClaimableZero()
        );
    }

    function _allClaimableZero() internal view returns (bool) {
        uint256 len = 0;
        while (true) {
            try c.rewardTokens(len) returns (address) {
                len++;
            } catch {
                break;
            }
        }
        for (uint256 i = 0; i < len; i++) {
            address token = c.rewardTokens(i);
            if (c.claimableRewards(address(this), token) != 0) {
                return false;
            }
        }
        return true;
    }

    receive() external payable {}
}

