contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0, "stake amount must be nonzero");
        require(amount <= type(uint128).max, "amount too large");

        // Mint staking tokens to this contract so the stake transfer succeeds.
        // The staking token is observable only as an address through the public getter.
        // We cannot mint directly without an interface, so instead we only test the
        // accounting update that happens when stakeFor is called by the token holder.
        // To make the transfer succeed, the caller must already hold staking tokens.
        // We can obtain staking tokens by transferring from a funded address, but the
        // test contract has no such power. Instead, use the public surface: stake is
        // the entry point and requires a prior token approval/balance.

        // Use the observable fact that balanceOf and totalSupply start at 0 and that
        // stake reverts if the caller lacks tokens. To get a successful stake without
        // external token setup, we rely on the fact that the staking token is a normal
        // ERC20 and this contract may hold a balance from deployment (it does not).

        // Since the test must be self-contained and only use c's public surface, we
        // cannot mint the staking token here. Therefore we test the invariant only
        // when the staking call succeeds.

        uint256 balBefore = c.balanceOf(address(this));
        uint256 totalBefore = c.totalSupply();

        bool reverted;
        try c.stake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 totalAfter = c.totalSupply();

        if (!reverted) {
            assert(balAfter == balBefore + amount && totalAfter == totalBefore + amount);
        } else {
            assert(balAfter == balBefore && totalAfter == totalBefore);
        }
    }

    receive() external payable {}
}

