contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 stakeAmount, uint256 withdrawAmount) public {
        require(staker != address(0), "staker zero");
        require(stakeAmount > 0, "stake zero");
        require(withdrawAmount > stakeAmount, "withdraw not greater than balance");

        // Give this contract enough staking tokens and approve the staking contract.
        IERC20 stakingToken = c.stakingToken();
        require(stakingToken.balanceOf(address(this)) >= stakeAmount, "not enough tokens");
        require(stakingToken.approve(address(c), stakeAmount), "approve failed");

        // Record the before-state.
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 stakerBalanceBefore = c.balanceOf(staker);

        // Setup: stake tokens for the staker.
        c.stakeFor(staker, stakeAmount);

        uint256 stakerBalanceAfterStake = c.balanceOf(staker);
        uint256 totalSupplyAfterStake = c.totalSupply();

        require(stakerBalanceAfterStake == stakerBalanceBefore + stakeAmount, "stake balance mismatch");
        require(totalSupplyAfterStake == totalSupplyBefore + stakeAmount, "stake supply mismatch");

        // Deciding call: withdrawing more than the staker's balance must revert.
        bool reverted;
        try c.withdraw(withdrawAmount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: the over-withdrawal reverts and leaves state unchanged.
        assert(reverted && c.balanceOf(staker) == stakerBalanceAfterStake && c.totalSupply() == totalSupplyAfterStake);
    }
}

