    function run(address staker, uint256 amount) public {
        require(staker != address(0), "staker zero");
        require(amount > 0, "amount zero");

        // Read before values
        uint256 beforeBal = c.balanceOf(staker);
        uint256 beforeTotal = c.totalSupply();

        // Make the deciding call: attempt to stake as msg.sender (this contract)
        bool reverted;
        try c.stake(amount) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            // If the call succeeded, the staker's balance and total supply must increase by amount,
            // and the contract's staking token balance must have increased by amount.
            // (Since msg.sender is this contract, the staker of the successful call is this contract.)
            uint256 afterBal = c.balanceOf(address(this));
            uint256 afterTotal = c.totalSupply();
            assert(afterBal == beforeBal + amount && afterTotal == beforeTotal + amount);
        } else {
            // If the call reverted, the staker balance and total supply must be unchanged.
            assert(c.balanceOf(staker) == beforeBal && c.totalSupply() == beforeTotal);
        }
    }
}

