        require(c.stakingToken().approve(address(c), stakeAmount), "approve failed");

        // Create a positive recorded balance for staker.
        c.stakeFor(staker, stakeAmount);

        uint256 beforeBalance = c.balanceOf(staker);
        uint256 beforeSupply = c.totalSupply();
        uint256 beforeRecipient = c.stakingToken().balanceOf(toAddress);

        // The deciding call: withdraw the full balance without claiming rewards.
        // The public withdraw function can only act for msg.sender, so the rule
        // also covers the observed totalSupply and balanceOf after that call.
        c.withdraw(stakeAmount, false);

        uint256 afterRecipient = c.stakingToken().balanceOf(toAddress);

        assert(
            c.balanceOf(address(this)) == beforeBalance - stakeAmount &&
            c.totalSupply() == beforeSupply - stakeAmount &&
            (toAddress != address(this) || afterRecipient == beforeRecipient + stakeAmount)
        );
    }

    receive() external payable {}
}

