        require(stakeBalance >= amount, "not enough staking tokens");

        // Approve C to pull the staking tokens from this test contract.
        stakingToken.approve(address(c), amount);

        uint256 totalSupplyBefore = c.totalSupply();
        uint256 accountBalanceBefore = c.balanceOf(account);

        c.stakeFor(account, amount);

        // After staking, total supply and the staker's balance must have increased by exactly amount.
        assert(c.totalSupply() == totalSupplyBefore + amount && c.balanceOf(account) == accountBalanceBefore + amount);

        // Now withdraw the same amount without claiming rewards; the state should return to the before values.
        // Since msg.sender is this test contract, only call withdraw if the staker is this contract.
        // To make the test general, we directly call withdraw only when account == address(this); otherwise skip.
        // But the property must be general; we can instead use the fact that C allows only the staker to withdraw.
        // So we restrict account to be this test contract for the withdrawal check to be callable.
        // To keep the test general while still valid, we can just assert the stake effect and then conditionally
        // check the withdrawal round-trip when account is this contract.
        // However, the assert must be a single general rule. We will make the withdrawal part of the rule
        // by requiring account == address(this) as a precondition, but that would restrict generality.
        // Instead, we test the round-trip via a separate mechanism: we can have the test contract be the staker.
        // So we set account = address(this) implicitly? No, parameter is given. We'll use a second parameter for
        // the staker and require it is this contract for the withdrawal to be callable. That's a reasonable
        // precondition for this property.
        require(account == address(this), "account must be the test contract");

        c.withdraw(amount, false);

        assert(c.totalSupply() == totalSupplyBefore && c.balanceOf(account) == accountBalanceBefore);
    }

    receive() external payable {}
}

