contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        // The contract under test must have a positive balance for this staker.
        // We first create such a balance by staking a positive amount.
        require(amount > 0);

        uint256 stakeAmount = amount;

        // Read initial state through public getters.
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        // Drive the contract: stake then withdraw part of the stake.
        c.stake(stakeAmount);

        uint256 supplyAfterStake = c.totalSupply();
        uint256 balanceAfterStake = c.balanceOf(address(this));

        bool reverted;
        try c.withdraw(amount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));

        // General rule: after the withdrawal attempt, totalSupply and staker balance
        // are non-increasing relative to just before the withdrawal, and if the
        // withdrawal succeeded (did not revert) and the staker had enough balance,
        // then totalSupply decreased by exactly `amount` and the staker balance
        // decreased by exactly `amount`.
        if (!reverted) {
            assert(
                supplyAfter == supplyAfterStake - amount
                && balanceAfter == balanceAfterStake - amount
                && supplyAfter <= supplyAfterStake
                && balanceAfter <= balanceAfterStake
            );
        } else {
            assert(
                supplyAfter == supplyAfterStake
                && balanceAfter == balanceAfterStake
                && supplyAfter <= supplyBefore + stakeAmount
                && balanceAfter <= balanceBefore + stakeAmount
            );
        }
    }

    receive() external payable {}
}

