contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address stakerA, address stakerB, uint256 amountA, uint256 amountB) public payable {
        require(stakerA != address(0) && stakerB != address(0), "zero account");
        require(amountA > 0 && amountB > 0, "zero amount");
        require(address(this).balance >= amountA + amountB, "insufficient balance");

        // Fund this test contract so it can pay the staking token via a transferFrom-like path.
        // We assume the constructor-deployed staking token has already minted/approved to this
        // test contract; to keep it general we transfer through the token's transfer path by
        // staking directly is not possible without approval, so we just set up balances by
        // staking with pre-funded allowance assumed. The deciding calls below are the stake
        // and withdraw calls; the property is a state-consistency invariant.
        bool zeroStakeReverted;
        try c.stake(0) { zeroStakeReverted = false; } catch { zeroStakeReverted = true; }

        uint256 supplyBefore = c.totalSupply();

        c.stakeFor(stakerA, amountA);
        c.stakeFor(stakerB, amountB);

        uint256 balA1 = c.balanceOf(stakerA);
        uint256 balB1 = c.balanceOf(stakerB);
        uint256 supply1 = c.totalSupply();

        // Full withdrawal of A must reduce its balance to zero and reduce supply accordingly.
        c.withdrawAll(false, stakerA);

        uint256 balA2 = c.balanceOf(stakerA);
        uint256 supply2 = c.totalSupply();

        assert(
            zeroStakeReverted &&
            supplyBefore == 0 &&
            supply1 == supplyBefore + balA1 + balB1 &&
            supply2 + balA1 == supply1 &&
            balA2 == 0
        );
    }

    receive() external payable {}
}

