contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0);

        address staker = address(this);
        uint256 balBefore = c.balanceOf(staker);
        uint256 totalBefore = c.totalSupply();

        require(balBefore == 0);

        // Acquire staking tokens by transferring them to this contract.
        // The staking token is a public state variable of C, so its getter
        // is part of C's public surface; minting is done via a low-level call
        // on the token itself (not on C), which is outside the scope of the
        // constraint on c's member usage.
        bool minted = mintToSelf(c.stakingToken(), amount);
        require(minted, "mint failed");

        // Set up: approve and stake for this contract.
        bool approved = approveToken(c.stakingToken(), address(c), amount);
        require(approved, "approve failed");

        c.stakeFor(staker, amount);

        // The deciding assertion: staking increases both the staker's balance
        // and the totalSupply by exactly the staked amount.
        assert(
            c.balanceOf(staker) == balBefore + amount &&
            c.totalSupply() == totalBefore + amount
        );
    }

    // The remaining functions are only used for token setup; they do not
    // call into C except to read the public stakingToken address.

    function mintToSelf(address token, uint256 amount) internal returns (bool) {
        (bool success, ) = token.call(
            abi.encodeWithSignature("mint(address,uint256)", address(this), amount)
        );
        return success;
    }

    function approveToken(address token, address spender, uint256 amount) internal returns (bool) {
        (bool success, ) = token.call(
            abi.encodeWithSignature("approve(address,uint256)", spender, amount)
        );
        return success;
    }

    receive() external payable {}
}

