        require(_staker != address(0), "zero staker");
        require(_amount > 0, "zero amount");
        require(_staker != address(this), "test contract as staker");

        // Put the staker in a valid state first: stake a positive amount for _staker.
        uint256 supplyBeforeStake = c.totalSupply();
        uint256 balBeforeStake = c.balanceOf(_staker);

        c.stakeFor(_staker, _amount);

        require(c.totalSupply() == supplyBeforeStake + _amount, "stake supply mismatch");
        require(c.balanceOf(_staker) == balBeforeStake + _amount, "stake balance mismatch");

        // Now withdraw everything back.
        uint256 supplyBeforeWithdraw = c.totalSupply();
        uint256 balBeforeWithdraw = c.balanceOf(_staker);

        // withdrawAll uses msg.sender, so we must be the staker; only callable for our own account.
        // We use withdraw with the full balance instead to exercise the same invariant for _staker.
        uint256 fullBalance = balBeforeWithdraw;
        c.withdraw(fullBalance, _claim);

        uint256 supplyAfterWithdraw = c.totalSupply();
        uint256 balAfterWithdraw = c.balanceOf(_staker);

        assert(
            balAfterWithdraw == 0 &&
            supplyAfterWithdraw + fullBalance == supplyBeforeWithdraw
        );
    }

    receive() external payable {}
}

