        // Setup: stake an amount for this test contract.
        // For the stake to work, stakeAmount must be > 0 and the test contract must have
        // enough staking tokens and allowance; we only assert properties that are
        // meaningful when the setup calls succeed.
        require(stakeAmount > 0, "amount must be positive");

        // The test contract is the staker. Attempt the stake.
        // If it reverts (e.g., no tokens), the rest of the test is not meaningful.
        try c.stake(stakeAmount) {
            // stake succeeded
        } catch {
            // If staking failed, there is nothing to withdraw; return without asserting.
            return;
        }

        uint256 balanceBefore = c.balanceOf(address(this));

        // Try withdrawing withdrawAmount.
        bool reverted;
        try c.withdraw(withdrawAmount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.balanceOf(address(this));

        if (reverted) {
            // A failed withdraw must not change the staked balance.
            assert(balanceAfter == balanceBefore);
        } else {
            // A successful withdraw must have been for at most the staked balance,
            // and must not underflow: balanceAfter = balanceBefore - withdrawAmount >= 0.
            assert(withdrawAmount <= balanceBefore);
            assert(balanceAfter == balanceBefore - withdrawAmount);
        }
    }

    receive() external payable {}
}

