                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (reverted) {
            assert(c.totalSupply() == supplyBefore && c.balanceOf(address(this)) == balanceBefore);
        } else {
            assert(
                c.totalSupply() == supplyBefore - withdrawAmount &&
                c.balanceOf(address(this)) == balanceBefore - withdrawAmount
            );
        }
    }
}

